          rootZ+cz*(reach+along*Math.sin(angleAt))+sideZ*u*width);"},"limits":"No matched centimeter-scale photo of this 19cm camera. The label geometryC is a mesh-version identifier. No independent withheld boxes or their unblinded scores are disclosed here.","windReality":{"note":"Three registered framebuffer snapshots at fixed 19cm view. Differences in 9 fixed regions quantify rendered change and return to rest, not tracked physical leaf displacement.","files":{"start":"782baf223e1893deb18e8f898d44c832e590929e0147239614f5fbde9625efba","wind4":"0e23dbfcfe51a449fb2b2242e62cc668346af22c1371a84a8bba8dd0cfca3102","rest":"8145976e8b3dede02cd1b6be031ef9068c065fbcaa6c301352f76279955a9327"},"regions":[[160,325,256,389],[453,325,549,389],[748,325,844,389],[160,465,256,529],[453,465,549,529],[748,465,844,529],[160,625,256,689],[453,625,549,689],[748,625,844,689]],"vsStart":{"wind4":{"changedAtLeast2CodeValues":0.5209780092592593,"meanAbsCodeValue":4.668848861882716,"p90MaxChannelCodeValue":19.0,"pixels":55296},"rest":{"changedAtLeast2CodeValues":0.1228298611111111,"meanAbsCodeValue":0.8293065200617284,"p90MaxChannelCodeValue":3.0,"pixels":55296}}},"frozenDecisionChecks":{"return_mean_lower_than_gust":{"actual":0.8293065200617284,"op":"<","reference":4.668848861882716,"units":"8-bit color code mean"},"exact_pixel_return":{"actual":0.8293065200617284,"op":"==","reference":0,"units":"8-bit color code mean"},"fixed_socket_error":{"actual":3.725290298461914e-06,"op":"<=","reference":0.001,"units":"mm"},"grounded_extra_leaves":{"actual":2.0825007140956586e-06,"op":"<=","reference":0.001,"units":"mm"}}},"imageInputs":{"jpegSha256":"d6c4347f9d49e23fe17a2ffac13b63845387e3eb4d2015f8e853eb2d17d3118d","sources":[{"label":"start","sourceSha256":"782baf223e1893deb18e8f898d44c832e590929e0147239614f5fbde9625efba","box":[235,375,747,539]},{"label":"wind","sourceSha256":"0e23dbfcfe51a449fb2b2242e62cc668346af22c1371a84a8bba8dd0cfca3102","box":[235,375,747,539]},{"label":"return","sourceSha256